(()=>{'use strict';const C=window.DEMO_CONTEXT,P=window.DEMO_PAGE,A=window.REVIEWED_V19_ASSETS;if(!C||!P||!A)return;const root=P.workbenchRoot||P.id,a=A[root];if(!a)return;const detail=P.kind==='WORKBENCH_DETAIL',key='reviewed-v19-filter-'+root,returnKey='reviewed-v19-return-'+root,accountKey='reviewed-v19-account-'+root;
const $=(s,e=document)=>e.querySelector(s),$$=(s,e=document)=>[...e.querySelectorAll(s)],norm=s=>String(s||'').replace(/\s+/g,'');const el=html=>{const t=document.createElement('template');t.innerHTML=html;return t.content.firstElementChild;};
let drawer=null,picker=null,mode='',configIndex=0,replaceAt=-1,state={draft:[],applied:[]};try{state={...state,...JSON.parse(sessionStorage.getItem(key)||'{}')};}catch{}const remember=()=>sessionStorage.setItem(key,JSON.stringify(state));
function hidePicker(){picker?.remove();picker=null;replaceAt=-1;}
function read(){if(mode!=='filter'||!drawer)return;state.draft=$$('.row__pv_MT[data-field]',drawer).map(row=>({field:row.dataset.field,values:$$('input',row).slice(1).map(x=>x.value)}));remember();}
function close(){read();hidePicker();drawer?.remove();drawer=null;mode='';}
function shell(html,width=550){const wrap=document.createElement('div');wrap.className='kodo-new-drawer kodo-new-drawer-right css-uy6x3o kodo-new-drawer-open';wrap.dataset.reviewedV19Drawer='true';wrap.innerHTML='<div class="kodo-new-drawer-mask"></div><div class="kodo-new-drawer-content-wrapper"></div>';$('div.kodo-new-drawer-content-wrapper',wrap).style.width=Math.min(width,innerWidth)+'px';$('div.kodo-new-drawer-content-wrapper',wrap).append(el(html));wrap.style.fontSize='14px';wrap.style.lineHeight='22px';wrap.style.fontFamily='-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,"Noto Sans",sans-serif';document.body.append(wrap);drawer=wrap;const closeButton=$('.kodo-new-drawer-header button',wrap);if(closeButton)closeButton.setAttribute('aria-label','关闭面板');}
function renderRows(){const area=$('.addFilterCriteria__ZxHpo',drawer)?.parentElement;if(!area)return;$$('.row__pv_MT[data-field]',area).forEach(e=>e.remove());for(const [i,item]of state.draft.entries()){const schema=a.filter.fields.find(x=>x.name===item.field);if(!schema)continue;const row=el(schema.html);row.dataset.field=item.field;row.dataset.kind=schema.kind;row.dataset.conditionIndex=String(i);const inputs=$$('input',row).slice(1);inputs.forEach((input,index)=>{input.value=item.values?.[index]||'';input.setAttribute('aria-label',item.field+' · '+(input.placeholder||'值')+' '+(index+1));});const remove=$('.deleteIcon__R1Qq6',row);if(remove){remove.setAttribute('role','button');remove.setAttribute('aria-label','删除条件 '+item.field);remove.tabIndex=0;}area.append(row);}}
function filter(){close();mode='filter';shell(a.filter.defaultHTML);renderRows();}
function config(index=0){close();mode='config';configIndex=index;shell(a.configs[index].html);}
function paintPicker(){if(!picker)return;for(const label of $$('.fieldName__C_Mkx',picker))label.parentElement.classList.toggle('disabled__WvPNr',state.draft.some((x,i)=>x.field===label.textContent.trim()&&i!==replaceAt));}
function fields(anchor,at=-1){read();hidePicker();replaceAt=at;picker=el(a.filter.pickerHTML);picker.dataset.reviewedV19Picker='true';picker.style.position='fixed';picker.style.inset='auto';picker.style.zIndex='2147483550';picker.style.fontSize='14px';picker.style.lineHeight='22px';const r=anchor.getBoundingClientRect();picker.style.left=Math.min(r.left,innerWidth-240)+'px';picker.style.top=Math.min(r.bottom+4,innerHeight-420)+'px';document.body.append(picker);paintPicker();const search=$('input',picker);if(search){search.setAttribute('aria-label','搜索筛选字段');search.focus();}}
function terms(items){const out=[];for(const item of items){const type=a.filter.fields.find(x=>x.name===item.field)?.kind,values=item.values||[];if(['date','person'].includes(type))continue;if(type==='number'){values.forEach((value,i)=>{if(String(value).trim()!=='')out.push({field:item.field,fields:[item.field],value,op:i===0?'min':'max',reviewedWorkbench:true});});}else if(String(values[0]||'').trim())out.push({field:item.field,fields:[item.field],value:values[0].trim(),op:'contains',reviewedWorkbench:true});}return out;}
function count(){return state.applied.filter(x=>terms([x]).length).length;}
function paintCount(){if(detail)return;const b=$('button.filterButton__gqYsV,button.filterButton__s7OC6');if(!b)return;let badge=$('[data-reviewed-filter-count]',b);if(!count()){badge?.remove();b.classList.remove('hasValue__PrqVw');return;}if(!badge){badge=document.createElement('span');badge.dataset.reviewedFilterCount='true';b.prepend(badge);}badge.textContent=String(count());b.classList.add('hasValue__PrqVw');}
function apply(){read();state.applied=state.draft.map(x=>({field:x.field,values:[...x.values]}));remember();close();C.query();paintCount();}
if(!detail){const previous=C.transformQueryTerms;C.transformQueryTerms=items=>[...(previous?previous(items):items).filter(x=>!x.reviewedWorkbench),...terms(state.applied)];if(terms(state.applied).length)C.query();paintCount();}
if(detail){let account;try{account=JSON.parse(sessionStorage.getItem(accountKey)||'null');}catch{}const name=$('.right_title_text__wbKY5,.right_title_text__dxV_i');if(name&&account)name.textContent=account.fields[root==='BL-02-07'?'客户名称':'供应商名称']||'演示往来单位';if(account)$$('.pointer__K0oMX').forEach((node,i)=>{const value=$('.pointer_account_num__mLXO1',node);if(value)value.textContent=account.fields[a.states[i].label]??'0';});}
if(detail){const pins=()=>{for(const table of $$('.kodo-art-table')){const headers=$$('.kodo-art-table-thead .kodo-art-table-row',table)[0]?.children;if(!headers)continue;let left=0;[...headers].forEach((cell,i)=>{if(!cell.classList.contains('kodo-art-table-cell-fix-left'))return;cell.style.left=left+'px';for(const row of $$('.kodo-art-table-tbody .kodo-art-table-row',table)){const item=row.children[i];if(item?.classList.contains('kodo-art-table-cell-fix-left'))item.style.left=left+'px';}left+=cell.getBoundingClientRect().width;});}};pins();window.addEventListener('resize',pins);}
window.addEventListener('input',e=>{if(picker?.contains(e.target)){const q=e.target.value.trim().toLowerCase();for(const label of $$('.fieldName__C_Mkx',picker)){const row=label.parentElement;row.style.display=label.textContent.toLowerCase().includes(q)?'':'none';}return;}if(drawer?.contains(e.target))read();},true);
window.addEventListener('click',e=>{
 const button=e.target.closest('button'),label=norm(button?.textContent),stop=()=>{e.preventDefault();e.stopImmediatePropagation();};
 if(picker?.contains(e.target)){if(e.target.closest('input'))return;const item=e.target.closest('.fieldName__C_Mkx')||e.target.closest('[class*=field]')?.querySelector('.fieldName__C_Mkx');if(item){stop();const name=item.textContent.trim();if(!a.filter.fields.some(x=>x.name===name))return;read();if(state.draft.some((x,i)=>x.field===name&&i!==replaceAt))return;const replacing=replaceAt>=0;if(replacing)state.draft[replaceAt]={field:name,values:[]};else state.draft.push({field:name,values:[]});remember();renderRows();if(replacing)hidePicker();else paintPicker();}else stop();return;}
 if(picker)hidePicker();
 if(drawer?.contains(e.target)){
  if(e.target.closest('.kodo-new-drawer-mask')||button?.getAttribute('aria-label')==='关闭面板'){stop();close();return;}
  if(mode==='config'){stop();const tab=e.target.closest('[role=tab]');if(tab){const i=a.configs.findIndex(x=>x.tab===tab.textContent.trim());if(i>=0)config(i);}else if(label==='修改配置')C.toast('修改和保存配置尚待核对，当前可查看后关闭');return;}
  const remove=e.target.closest('.deleteIcon__R1Qq6');if(remove){stop();read();state.draft.splice(Number(remove.closest('[data-condition-index]').dataset.conditionIndex),1);remember();renderRows();return;}
  if(label==='添加筛选条件'){stop();fields(button);return;}
  if(label==='清空'){stop();read();state.draft.forEach(x=>x.values=x.values.map(()=>''));remember();renderRows();return;}
  if(label==='查询(Enter)'){stop();apply();return;}
  const select=e.target.closest('.filterItemSelectorWrapper__BYP20 .kodo-new-select-selector');if(select){stop();fields(select,Number(select.closest('[data-condition-index]').dataset.conditionIndex));return;}
  if(['person','date'].includes(e.target.closest('[data-kind]')?.dataset.kind)){stop();C.toast('人员和日期组合尚待核对，当前可查看或移除条件');return;}
  if(!e.target.closest('input,textarea')){stop();return;}return;
 }
 if(drawer){hidePicker();return;}
 if(label==='工作台引导'){stop();window.open(a.guide,'_blank','noopener,noreferrer');return;}
 if(!detail&&label==='查看详情'){stop();const row=button.closest('[data-demo-record]'),record=C.getLocalRecord?.(row?.dataset.demoRecord);if(record)sessionStorage.setItem(accountKey,JSON.stringify(record));location.href=a.states[0].id+'.html';return;}
 if(!detail&&/^\d*筛选$/.test(label)){stop();filter();return;}
 if(detail){if(label==='返回客户列表'||label==='返回供应商列表'){stop();state.applied=[];state.draft.forEach(x=>x.values=x.values.map(()=>''));remember();sessionStorage.removeItem(returnKey);location.href=root+'.html';return;}if(label==='工作台配置'){stop();config();return;}const pointer=e.target.closest('.pointer__K0oMX');if(pointer){stop();const i=$$('.pointer__K0oMX').indexOf(pointer);if(a.states[i])location.href=a.states[i].id+'.html';return;}if(/^创建|^编辑|^删除|^审批|^确认|^提交|^导出|^打印/.test(label)){stop();C.toast('此单据操作尚待核对，当前可切换明细或返回列表');return;}if(button&&/筛选|批量/.test(label)||e.target.closest('.filterFormDrawer__KnvFs .searchBtn__1lrqB,.filterFormDrawer__KnvFs .kodo-new-select-selector,.kodo-new-picker,.ant-picker')){stop();C.toast('此明细筛选尚待核对，暂不应用');return;}}
},true);
window.addEventListener('focusin',e=>{if(picker&&!picker.contains(e.target))hidePicker();},true);
window.addEventListener('keydown',e=>{if(!drawer)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(picker)hidePicker();else close();}else if(e.key==='Enter'&&mode==='filter'&&e.target.matches('input')){e.preventDefault();e.stopImmediatePropagation();apply();}},true);
})();
